  SELECT COUNT(*) INTO v_count FROM STG_INVOICE;
  IF v_count <> 0 THEN RAISE_APPLICATION_ERROR(-20004, 'STG_INVOICE debe estar vacia.'); END IF;
  SELECT COUNT(*) INTO v_count FROM STG_INVOICELINE;
  IF v_count <> 0 THEN RAISE_APPLICATION_ERROR(-20004, 'STG_INVOICELINE debe estar vacia.'); END IF;
  SELECT COUNT(*) INTO v_count FROM STG_MEDIATYPE;
  IF v_count <> 0 THEN RAISE_APPLICATION_ERROR(-20004, 'STG_MEDIATYPE debe estar vacia.'); END IF;
  SELECT COUNT(*) INTO v_count FROM STG_PLAYLIST;
  IF v_count <> 0 THEN RAISE_APPLICATION_ERROR(-20004, 'STG_PLAYLIST debe estar vacia.'); END IF;
  SELECT COUNT(*) INTO v_count FROM STG_PLAYLISTTRACK;
